    def __init__(self):
        self.root = None
    def insert(self, word, doc_id):
        self.root = insert(self.root, (word, doc_id))
    def search(self, word):
        node = self.root
        while node is not None:
            if word == node.value[0]:
                return node.value[1]
            if word < node.value[0]:
                node = node.left
            else:
                node = node.right
        return None
    def prefix_search(self, prefix):
        result = []
        def helper(node):
            if node is None:
                return
            if node.value[0].startswith(prefix):
                result.append((node.value[0], node.value[1]))
            if node.value[0] > prefix:
                helper(node.left)
            else:
                helper(node.left)
                helper(node.right)
        helper(self.root)
        return result

